bool BundleInstallChecker::GetPrivilegeCapabilityValue(
    const std::vector<std::string> &existInJson,
    const std::string &key,
    bool existInPreJson,
    bool existInProvision)
{
    if (find(existInJson.cbegin(), existInJson.cend(), key) != existInJson.cend()) {
        return existInPreJson;
    }
    return existInProvision;
}

void BundleInstallChecker::FetchPrivilegeCapabilityFromPreConfig(
    const std::string &bundleName,
    const std::vector<std::string> &appSignatures,
    AppPrivilegeCapability &appPrivilegeCapability)
{
#ifdef USE_PRE_BUNDLE_PROFILE
    LOG_D(BMS_TAG_INSTALLER, "bundleName: %{public}s, FetchPrivilegeCapabilityFromPreConfig start", bundleName.c_str());
    PreBundleConfigInfo configInfo;
    configInfo.bundleName = bundleName;
    if (!BMSEventHandler::GetPreInstallCapability(configInfo)) {
        LOG_D(BMS_TAG_INSTALLER, "bundleName: %{public}s is not exist in pre install capability list",
            bundleName.c_str());
        return;
    }
    bool match = false;
    for (const auto &signature : appSignatures) {
        if (MatchSignature(configInfo.appSignature, signature)) {
            match = true;
            break;
        }
    }
    if (!match && !MatchOldSignatures(bundleName, configInfo.appSignature)) {
        LOG_NOFUNC_E(BMS_TAG_INSTALLER, "bundleName: %{public}s signature verify failed in capability list",
            bundleName.c_str());
        return;
    }

    appPrivilegeCapability.allowUsePrivilegeExtension = GetPrivilegeCapabilityValue(configInfo.existInJsonFile,
        ALLOW_APP_USE_PRIVILEGE_EXTENSION,
        configInfo.allowUsePrivilegeExtension, appPrivilegeCapability.allowUsePrivilegeExtension);

}
// process ExtensionAbility
auto &innerExtensionInfos = innerBundleInfo.FetchInnerExtensionInfos();
for (auto iter = innerExtensionInfos.begin(); iter != innerExtensionInfos.end(); ++iter) {
    bool privilegeType = IsPrivilegeExtensionAbilityType(iter->second.type);
    if (privilegeType && !appPrivilegeCapability.allowUsePrivilegeExtension) {
        LOG_E(BMS_TAG_INSTALLER, "not allow use privilege extension");
        return ERR_APPEXECFWK_PARSE_PROFILE_PROP_CHECK_ERROR;
    }

    bool systemType = IsSystemExtensionAbilityType(iter->second.type);
    if (systemType && !applicationInfo.isSystemApp) {
        LOG_E(BMS_TAG_INSTALLER, "not allow use system extension");
        return ERR_APPEXECFWK_PARSE_PROFILE_PROP_CHECK_ERROR;
    }

// In this case, extension which be starting needs that caller should be the system app, otherwise not supported.
inline bool IsSystemCallerNeeded(const AppExecFwk::ExtensionAbilityType type)
{
    const std::unordered_set<AppExecFwk::ExtensionAbilityType> uiExtensionStartingSet = {
        AppExecFwk::ExtensionAbilityType::PHOTO_EDITOR,
        AppExecFwk::ExtensionAbilityType::INSIGHT_INTENT_UI,
        AppExecFwk::ExtensionAbilityType::LIVEVIEW_LOCKSCREEN,
        AppExecFwk::ExtensionAbilityType::LIVEVIEW_CARD,
        AppExecFwk::ExtensionAbilityType::SHARE,
        AppExecFwk::ExtensionAbilityType::ACTION,
        AppExecFwk::ExtensionAbilityType::STATUS_BAR_VIEW,
        AppExecFwk::ExtensionAbilityType::VOIP,
        AppExecFwk::ExtensionAbilityType::FORM_EDIT,
        AppExecFwk::ExtensionAbilityType::LIVE_FORM
    };
    return uiExtensionStartingSet.find(type) != uiExtensionStartingSet.end();

int AbilityManagerService::CheckUIExtensionPermission(const AbilityRequest &abilityRequest, int32_t validUserId)
{
    if (abilityRequest.want.HasParameter(AAFwk::SCREEN_MODE_KEY)) {
        // If started by embedded atomic service, allow it.
        return ERR_OK;
    } 

    auto extensionType = abilityRequest.abilityInfo.extensionAbilityType;
    if (AAFwk::UIExtensionWrapper::IsSystemUIExtension(extensionType)) {
        auto callerRecord = Token::GetAbilityRecordByToken(abilityRequest.callerToken);
        if (callerRecord == nullptr) {
            TAG_LOGE(AAFwkTag::ABILITYMGR, "invalid caller");
            return NO_FOUND_ABILITY_BY_CALLER;
        }

        if (!abilityRequest.appInfo.isSystemApp) {
            TAG_LOGE(AAFwkTag::ABILITYMGR, "bundle %{public}s want start or caller bundle %{public}s "
                "isn't system app, type %{public}d not allowed", abilityRequest.appInfo.bundleName.c_str(),
                callerRecord->GetApplicationInfo().bundleName.c_str(), extensionType);
            return CHECK_PERMISSION_FAILED;
        }
    }

    uint32_t specifyTokenId = static_cast<uint32_t>(abilityRequest.specifiedFullTokenId);
    if (AAFwk::UIExtensionWrapper::IsSystemCallerNeeded(extensionType)) {
        auto callerRecord = Token::GetAbilityRecordByToken(abilityRequest.callerToken);
        if (callerRecord == nullptr) {
            TAG_LOGE(AAFwkTag::ABILITYMGR, "invalid caller");
            return NO_FOUND_ABILITY_BY_CALLER;
        }

        if (!callerRecord->GetApplicationInfo().isSystemApp
            && !AAFwk::PermissionVerification::GetInstance()->IsSACallByTokenId(specifyTokenId)) {
            TAG_LOGE(AAFwkTag::ABILITYMGR,
                     "bundle %{public}s want start but caller bundle %{public}s "
                     "isn't system app, type %{public}d not allowed",
                     abilityRequest.appInfo.bundleName.c_str(), callerRecord->GetApplicationInfo().bundleName.c_str(),
                     extensionType);
            return CHECK_PERMISSION_FAILED;
        }
    }

    if (!CheckUIExtensionCallerIsForeground(abilityRequest)) {
        return CHECK_PERMISSION_FAILED;
    }

    if (!CheckUIExtensionCallerPidByHostWindowId(abilityRequest, validUserId)) {
        return ERR_INVALID_CALLER;
    }

    return ERR_OK;

